  [('brn', '臨床'), ('bm', '2択')],
  '<span class="kw">次の文を読み、162 ～164 の問いに答えよ。</span><br/>80 歳の男性。胸痛のため救急車で搬入された。<br/><b>現病歴：</b>昨日午後7 時ころ夕食中に急に胸部絞扼感を感じた。胸痛は約30 分持続したが自然に軽快し、その日は就寝した。本日朝6 時、起床時に昨晩と同様の胸痛が出現した。昨夜より症状が強く動けない状態が持続し、その後呼吸困難も生じてきたため救急車を要請し、午前7 時に救急搬送された。<br/><b>既往歴：</b>10 年前から高血圧症で通院加療中。<br/><b>生活歴：</b>妻と2 人暮らし。喫煙は20 本/ 日、60 年間。飲酒は機会飲酒。<br/><b>家族歴：</b>特記すべきことはない。<br/><b>現\u3000症：</b>意識は清明。身長155cm、体重60kg。心拍数108/ 分、整。血圧106/86mmHg で明らかな左右差を認めない。呼吸数20/ 分。SpO<sub>2</sub> 94％（リザーバー付マスク10L/ 分酸素投与下）。冷汗を認める。眼瞼結膜と眼球結膜とに異常を認めない。頸静脈の怒張を認める。心音はⅢ音ギャロップを呈しており、心尖部を最強点とするLevine3/6 の収縮期雑音を聴取する。呼吸音は両側中下胸部に湿性ラ音を聴取する。腹部は平坦、軟で、肝・脾を触知しない。下腿に浮腫を認めない。<br/><b>検査所見：</b>赤血球463 万、Hb 13.2g/dL、Ht 40％、白血球9,800、血小板28 万、総ビリルビン0.5mg/dL、AST 118U/L、ALT 32U/L、LD 320U/L（基準120 ～245）、CK 346U/L（基準30 ～140）、尿素窒素12mg/dL、クレアチニン0.8mg/dL、血糖98mg/dL、Na 138mEq/L、K 4.4mEq/L、Cl 97mEq/L。心筋トロポニンT 迅速検査陽性。心電図は心拍数108/ 分の洞調律で、広範な誘導でST 低下を認めた。<br/><strong>この患者の病態で正しいのはどれか。2 つ選べ。</strong>',
