   ('ep', '💔 急性心筋梗塞の機械的合併症',
    '発症数日〜1週の亜急性期に、壊死した心筋が破綻して起こる。<br>・<span class="kw">自由壁破裂（心破裂）</span>：blow-out型は急激な心タンポナーデから心停止に至り予後不良。oozing型は緩徐でドレナージ・手術が間に合うことがある。<br>・<span class="kw">乳頭筋断裂</span>：後乳頭筋は後下行枝のみの単一血行支配のため、二重支配の前乳頭筋より断裂しやすい。急性僧帽弁閉鎖不全から急性肺水腫。<br>・<span class="kw">心室中隔穿孔</span>：左右短絡による心不全。外科修復が基本だが、ハイリスク例では経カテーテル閉鎖術も選択肢となる。<br>・<span class="kw">房室ブロック</span>：房室結節は右冠動脈支配なので<span class="kw">下壁梗塞</span>で生じやすい（前壁梗塞では脚ブロックが多い）。'),
