  '<span class="kw">次の文を読み、186 ～188 の問いに答えよ。</span><br/>46 歳の男性。心窩部から左前胸部にかけての痛みを主訴に来院した。<br/><b>現病歴：</b>本日、午前9 時、職場の会議中に心窩部から左前胸部にかけての締め付けられるような痛みが出現した。同時に咽頭部と左肩にも痛みを感じたという。そのまま安静にしていたところ、15 分程度で改善したため様子をみていたが、午前9 時30 分、会議終了時に再び発作が生じた。これも15 分程度で治まったが、症状が繰り返すため心配になって、仕事を早退して午前10 時30 分に来院した。<br/><b>既往歴：</b>10 年前から高血圧症と脂質異常症で内服治療中。<br/><b>生活歴：</b>妻と2 人暮らし。喫煙は40 歳まで10 本/ 日を20 年間。飲酒は機会飲酒。<br/><b>家族歴：</b>特記すべきことはない。<br/><b>現\u3000症：</b>意識は清明。身長162cm、体重60kg。脈拍60/ 分、整。血圧140/80mmHg で左右差を認めない。呼吸数16/ 分。SpO<sub>2</sub> 99％（room air）。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。<br/><b>検査所見：</b>尿所見：蛋白（－）、糖（－）。血液所見：赤血球450 万、Hb 13.3g/dL、Ht 40％、白血球6,200（桿状核好中球2％、分葉核好中球58％、好酸球3％、好塩基球1％、単球8％、リンパ球28％）、血小板18 万、D ダイマー0.6μg/mL（基準1.0 以下）。血液生化学所見：AST 32U/L、ALT 45U/L、LD 260U/L（基準176 ～353）、CK98U/L（基準30 ～140）、尿素窒素11mg/dL、クレアチニン0.9mg/dL。心筋トロポニンT 陰性。胸部エックス線写真（A）と心電図（B）とを示す。心エコーで前壁から心尖部にかけて軽度の収縮性低下を認める。<br/><strong>最も疑われるのはどれか。</strong>',
